"""FM-16AP: singular products, projected skewness and distance comparison."""
import sympy as s
from calibration_bank import L
from calibration_g_bank import make as matrix
from calibration_p_bank import make as skew
from calibration_c_bank import make as distance
TARGETS={('singular-condition',6),('justify-skew',6),('line-line-distance',6)}

def revise(path,tier,v):
    if (path,tier) not in TARGETS or v not in (1,2,3): raise ValueError('Not FM-16AP')
    a=s.Integer(v+1); b=a+2; h,k=s.symbols('h k',real=True)
    if path=='singular-condition':
        p=matrix(path,tier,v); A=s.Matrix([[1,a],[k,-1]]); B=s.Matrix([[h,1],[1,k]]); C=A*B; K=-1/a
        question=f'Let A={L(A)} and B={L(B)}, where h,k are real. Classify every pair (h,k) for which AB is invertible, nonzero singular, or the zero matrix. Determine which factors are singular in each case and prove completeness.'
        answer=f'Zero product exactly at (h,k)=({-a},{L(K)}); both factors singular. Nonzero singular exactly when one of k={L(K)} and hk=1 holds, but not both. Invertible when neither holds.'
        steps=[f'The determinants are {L(A.det())} and {L(B.det())}. Thus AB is singular exactly when k={L(K)} or hk=1.',f'Both factors are singular exactly at k={L(K)}, h={-a}. Direct multiplication gives AB={L(C)}; at that pair all entries vanish.', 'If exactly one factor is singular, the other is invertible. A zero product would force the singular factor itself to be zero by multiplying by the inverse, impossible because each factor has an entry 1.', 'If neither determinant vanishes, the determinant of the product is nonzero. The mutually exclusive cases exhaust the parameter plane.']
        facts=[A.det(),B.det(),K,-a,*C]; hints=['Use the determinant product rule first.','When only one factor is singular, use the inverse of the other to exclude a zero product.']; mistake='Assuming every singular product is the zero matrix.'; rationale='Distinguish singularity from annihilation using two parameter conditions and inverse reasoning.'
        rub=[('M',1,'Derive both determinant conditions.'),('A',1,'Find the simultaneous singular pair.'),('A',1,'Verify the zero product at that pair.'),('R',2,'Prove the product is nonzero if exactly one factor is singular; inverse or direct entry method accepted.'),('R',1,'Classify the remaining region and establish completeness.')]
    elif path=='justify-skew':
        p=skew(path,tier,v); T=a/(1-k); U=-h; V=a-k*h; P=s.Matrix([-h,-h,0])
        question=f'Lines L and M have points (t,t,0) and (u,{a}+ku,h+u), respectively. For real h,k, project both lines onto the xy-plane and yz-plane by dropping the remaining coordinate. Find the intersection parameters in each projection, when they exist. Determine exactly when both projections intersect but the original lines are skew, and when the original lines intersect. Justify all exceptional cases.'
        answer=f'xy: no intersection for k=1; otherwise t=u={L(T)}. yz: u={L(U)}, t={L(V)} for all h,k. Both projections intersect but the lines are skew iff k differs from 1 and h(k-1) differs from {a}. Original lines intersect iff h(k-1)={a}, at {L(P)}. For k=1 the original lines are always skew.'
        steps=[f'In xy the equations are t=u and t={a}+ku. If k=1 they contradict because {a} is nonzero; otherwise t=u={L(T)}.',f'In yz the equations are t={a}+ku and 0=h+u, so u={L(U)}, t={L(V)} uniquely.',f'A common point in space requires the same parameters in both projections. For k not equal to 1 this is equivalent to {L(T)}=-h, or h(k-1)={a}; then the point is {L(P)}.', 'The direction vectors (1,1,0) and (1,k,1) cannot be parallel because their third components differ and both have first component 1. Thus every nonintersection is skew, including k=1. The cases exhaust all parameters.']
        facts=[T,U,V,a,*P]; hints=['Keep the line parameters when projecting.','An intersection in each projection need not use the same parameter values.']; mistake='Assuming intersecting projections guarantee a common point in three dimensions.'; rationale='Test coplanarity by parameter consistency across two projections, rather than another direct coordinate classification.'
        rub=[('M',1,'Form both projected equation pairs.'),('A',2,'Solve each projected system including the exceptional case; one mark per projection.'),('R',1,'Establish the necessary and sufficient common-parameter condition.'),('A',1,'Give the common point.'),('R',1,'Exclude parallel directions and classify all skew cases.')]
    else:
        p=distance(path,tier,v); tp=(h-b)/3; up=-(h+2*b)/3; tm=(h+b)/3; um=-(h-2*b)/3; dp=s.Abs(h-b)/s.sqrt(3); dm=s.Abs(h+b)/s.sqrt(3)
        question=f'Let L have points (t,t,0), and let M+ and M- have points (h+u,0,{b}+u) and (h+u,0,{-b}+u), respectively. For every real h find the closest pair of points between L and each of M+ and M-. Give both distances, prove each pair is uniquely closest, and determine which line is nearer to L, including equality and zero-distance cases.'
        answer=f'For M+: t={L(tp)}, u={L(up)}, distance {L(dp)}. For M-: t={L(tm)}, u={L(um)}, distance {L(dm)}. Substitute the parameters in the stated lines for both point pairs. M+ is nearer for h positive, M- for h negative, and equal at h=0. Distances vanish only at h={b} for M+ and h={-b} for M-.'
        steps=[f'Write d={b} or d={-b}. The displacement from M to L is (t-h-u,t,-d-u). At the closest pair it is perpendicular to both directions (1,1,0) and (1,0,1).', 'The dot products give 2t=h+u and t-h-u-d-u=0. Solving yields t=(h-d)/3 and u=-(h+2d)/3.', 'At these values the displacement is (t,-t,-t). Any other pair changes this displacement by a linear combination of the two directions, perpendicular to it. The squared distance therefore increases by the squared norm of that change; the independent directions make this strictly positive unless both parameters are unchanged.',f'Substitution gives the two parameter pairs and distances {L(dp)} and {L(dm)}. Comparing squares gives (h-{b}) squared minus (h+{b}) squared = -{4*b}h.',f'Thus the nearer line depends on the sign of h and the distances are equal only at zero. A distance vanishes exactly when h equals the corresponding signed offset.']
        facts=[tp,up,tm,um,dp,dm,b,-b]; hints=['Use a signed offset d to solve both closest-pair problems at once.','Compare squared distances, and use orthogonality to prove the minimum.']; mistake='Comparing the distances between arbitrary points rather than minimising each pair.'; rationale='Solve two coupled closest-point problems and compare the minima, proving uniqueness geometrically.'
        rub=[('M',2,'Form both orthogonality equations; one mark each.'),('A',2,'Find both closest parameter pairs; one mark each.'),('R',2,'Prove global minimality and uniqueness by orthogonal decomposition; equivalent positive quadratic proof accepted.'),('A',1,'Obtain both distances; follow through consistent parameters.'),('R',1,'Compare distances and identify equality and zero-distance cases.')]
    p.update(question_latex=question,final_answer_latex=answer,worked_solution_latex=steps,progressive_hints=hints,likely_mistake=mistake,demand_rationale=rationale,facts=[str(s.simplify(f)) for f in facts],rubric=[{'type':t,'marks':m,'criterion':c} for t,m,c in rub]);return p
